internal fun pr18FullBounds(node: SemanticsNode): Rect = Rect(node.positionInRoot.x, node.positionInRoot.y,
    node.positionInRoot.x + node.size.width, node.positionInRoot.y + node.size.height)
internal fun pr18OuterCoordinates(node: SemanticsNode): androidx.compose.ui.layout.LayoutCoordinates {
    var coordinates = node.layoutInfo.coordinates
    val parent = coordinates.parentLayoutCoordinates
    // Public pinned LayoutCoordinates: parentCoordinates traverses modifiers;
    // parentLayoutCoordinates is outside this LayoutNode's outer coordinator.
    while (coordinates.parentCoordinates != null && coordinates.parentCoordinates !== parent) {
        coordinates = requireNotNull(coordinates.parentCoordinates)
    }
    return coordinates
}
fun hasText(
    text: String,
    substring: Boolean = false,
    ignoreCase: Boolean = false
): SemanticsMatcher {
    val propertyName = "${Text.name} + ${InputText.name} + ${EditableText.name}"
    return if (substring) {
        SemanticsMatcher("$propertyName contains '$text' (ignoreCase: $ignoreCase) as substring") {
            val isInInputTextValue =
                it.config.getOrNull(InputText)?.text?.contains(text, ignoreCase) ?: false
            val isInEditableTextValue =
                it.config.getOrNull(EditableText)?.text?.contains(text, ignoreCase) ?: false
            val isInTextValue =
                it.config.getOrNull(Text)?.any { item -> item.text.contains(text, ignoreCase) }
                    ?: false
            isInInputTextValue || isInEditableTextValue || isInTextValue
        }
    } else {
        SemanticsMatcher("$propertyName contains '$text' (ignoreCase: $ignoreCase)") {
            val isInInputTextValue =
                it.config.getOrNull(InputText)?.text?.equals(text, ignoreCase) ?: false
            val isInEditableTextValue =
                it.config.getOrNull(EditableText)?.text?.equals(text, ignoreCase) ?: false
            val isInTextValue =
                it.config.getOrNull(Text)?.any { item -> item.text.equals(text, ignoreCase) }
                    ?: false
            isInInputTextValue || isInEditableTextValue || isInTextValue
        }
    }
}

fun hasTextExactly(
    vararg textValues: String,
    includeEditableText: Boolean = true
): SemanticsMatcher {
    val expected = textValues.toList()
    val propertyName =
        if (includeEditableText) {
            "${Text.name} + ${EditableText.name}"
        } else {
            Text.name
        }
    return SemanticsMatcher("$propertyName = [${textValues.joinToString(",")}]") { node ->
        val actual = mutableListOf<String>()
        if (includeEditableText) {
            node.config.getOrNull(EditableText)?.let { actual.add(it.text) }
        }
        node.config.getOrNull(Text)?.let { actual.addAll(it.map { anStr -> anStr.text }) }
        actual.containsAll(expected) && expected.containsAll(actual)
    }
}
fun SemanticsNodeInteraction.assertTextContains(
    value: String,
    substring: Boolean = false,
    ignoreCase: Boolean = false
): SemanticsNodeInteraction = assert(hasText(value, substring = substring, ignoreCase = ignoreCase))

fun SemanticsNodeInteraction.assertTextEquals(
    vararg values: String,
    includeEditableText: Boolean = true
): SemanticsNodeInteraction =
    assert(hasTextExactly(*values, includeEditableText = includeEditableText))

class AdapterProbe(val compose: FixtureCompose, val windows: List<AccessibilityWindowInfo>) {
    val logs = mutableListOf<String>()
    private fun ownerWindow(view: View) = view.window
    private fun record(line: String) { logs += line }
    private fun interactiveWindows() = windows
    private fun windowRectangles(window: AccessibilityWindowInfo) = window.rectangles
    private fun keyboardRectangles(windows: List<AccessibilityWindowInfo>): List<AndroidRect> =
        windows.filter { it.type == AccessibilityWindowInfo.TYPE_INPUT_METHOD }.flatMap { it.rectangles }
    private data class TouchGeometry(
        val root: View, val window: Window, val full: Rect, val clipped: Rect,
        val windowFull: Rect, val windowClipped: Rect, val point: Offset,
        val screenOrigin: Offset, val visible: Rect, val overlays: List<Pair<String, Rect>>,
        val configuration: String,
    )
    private fun withOverlays(node: SemanticsNode, geometry: TouchGeometry): TouchGeometry {
        val ancestors = generateSequence(node) { it.parent }.map { it.id }.toSet()
        val candidates = compose.onAllNodes(SemanticsMatcher("actionable Compose surfaces") {
            it.config.contains(SemanticsActions.OnClick) || it.config.contains(SemanticsActions.OnLongClick) ||
                it.config.contains(SemanticsActions.ScrollBy) || it.config.contains(SemanticsActions.SetText) ||
                it.config.contains(SemanticsActions.SetProgress)
        }, true).fetchSemanticsNodes()
        val overlays = compose.runOnIdle { candidates.filter {
            it.id !in ancestors && ownerWindow((it.root as ViewRootForTest).view) === geometry.window
        }.mapNotNull { overlay ->
            // Coordinates from a different Compose root must first go through screen space.
            val view = (overlay.root as ViewRootForTest).view
            val origin = IntArray(2).also { view.getLocationOnScreen(it) }
            val outer = pr18OuterCoordinates(overlay)
            val position = outer.positionInRoot()
            val full = Rect(position.x, position.y, position.x + outer.size.width, position.y + outer.size.height)
            val windowPosition = outer.positionInWindow()
            val label = "node-${overlay.id}:${overlay.config.getOrElse(SemanticsProperties.TestTag) { "untagged" }}"
            record("overlay tag=$label owner=${System.identityHashCode(geometry.window)} " +
                "root=${System.identityHashCode(view)} outerFull=$full outerClipped=${outer.boundsInRoot()} " +
                "windowPosition=$windowPosition size=${outer.size} semanticFull=${pr18FullBounds(overlay)} semanticClipped=${overlay.boundsInRoot}")
            outer.boundsInRoot().takeIf { it.width > 0 && it.height > 0 }?.let { bounds ->
                label to bounds.translate(Offset(origin[0].toFloat(), origin[1].toFloat()) - geometry.screenOrigin)
            }
        } }.toMutableList()
        val windows = interactiveWindows()
        val ownerId = compose.runOnIdle {
            val info = geometry.root.createAccessibilityNodeInfo()
            try { requireNotNull(info).windowId } finally { info?.recycle() }
        }
        val owner = windows.singleOrNull { it.id == ownerId } ?: error("Screen owner window availability is unknown")
        for (window in windows.filter { it.id != ownerId && it.layer > owner.layer && it.type != AccessibilityWindowInfo.TYPE_INPUT_METHOD }) {
            for ((index, bounds) in windowRectangles(window).withIndex()) overlays += "window-${window.id}-$index" to
                Rect(bounds.left.toFloat(), bounds.top.toFloat(), bounds.right.toFloat(), bounds.bottom.toFloat()).translate(-geometry.screenOrigin)
        }
        val keyboards = keyboardRectangles(windows)
        for ((index, keyboard) in keyboards.withIndex()) overlays += "IME-screen-$index" to Rect(keyboard.left.toFloat(), keyboard.top.toFloat(),
            keyboard.right.toFloat(), keyboard.bottom.toFloat()).translate(-geometry.screenOrigin)
        val imeVisible = compose.runOnIdle {
            requireNotNull(ViewCompat.getRootWindowInsets(geometry.root)) { "Touch owner IME insets unavailable" }
                .isVisible(WindowInsetsCompat.Type.ime())
        }
        check(!imeVisible || keyboards.isNotEmpty()) { "IME visible but its actual screen geometry is unknown" }
        return geometry.copy(overlays = overlays)
    }

    private fun observedGeometry(node: SemanticsNode): TouchGeometry {
        val view = node.root.view
        val full = pr18FullBounds(node)
        return withOverlays(node, TouchGeometry(view, view.window, full, node.boundsInRoot,
            full, node.boundsInRoot, full.center, Offset(view.x.toFloat(), view.y.toFloat()),
            view.visible, emptyList(), "CONTROL synthetic geometry"))
    }
    fun exposed(node: SemanticsNode): Boolean {
        val g = observedGeometry(node)
            val exposed = g.full.contains(g.point) && g.clipped.contains(g.point) && g.visible.contains(g.point) &&
                g.overlays.none { it.second.contains(g.point) }

        return exposed
    }
    fun overlays(node: SemanticsNode) = observedGeometry(node).overlays
    fun target(tag: String) = SemanticsNodeInteraction(compose.nodes.single {
        it.config.getOrElse(SemanticsProperties.TestTag) { "" } == tag
    })
    fun progress(state: ProgressState) {
        val evidence = this
evidence.target("update-progress").assertTextContains(if (state.stage == UpdateStage.VERIFYING) "正在校验安装包…"
                            else if (state.percent == null) "百分比待确认" else "50%")
    }
}
fun productionProgress(state: ProgressState): String = if (state.stage == UpdateStage.VERIFYING) "正在校验安装包…" else "正在下载 · ${state.percent?.let { "$it%" } ?: "百分比待确认"}"
